import 'package:flutter/material.dart';
import '../services/api_service.dart';

class HomeScreen extends StatefulWidget { const HomeScreen({super.key}); @override State<HomeScreen> createState()=>_HomeScreenState(); }
class _HomeScreenState extends State<HomeScreen>{ double balance=0; @override void initState(){super.initState(); load();} Future<void> load() async{final r=await ApiService.dio.get('/wallet'); setState(()=>balance=double.tryParse('${r.data['wallet']['balance']}')??0);} @override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Wallet')),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(20),children:[Container(padding:const EdgeInsets.all(24),decoration:BoxDecoration(borderRadius:BorderRadius.circular(32),gradient:const LinearGradient(colors:[Colors.indigo,Colors.blue])),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Saldo Anda',style:TextStyle(color:Colors.white70)),const SizedBox(height:8),Text('Rp ${balance.toStringAsFixed(0)}',style:const TextStyle(color:Colors.white,fontSize:34,fontWeight:FontWeight.w900))])),const SizedBox(height:20),const Text('Starter Flutter siap disambungkan ke layar top up, transfer, dan riwayat.',style:TextStyle(fontSize:16))])));}}
